#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "bicg.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Tunable scheduling constants (chosen for a modern multicore x64 CPU).
// TILE_* control the per-task chunk size when parallelizing the outer
// dimension; adjust for different cache sizes or core counts if desired.
static constexpr int TILE_J = 128;  // tiling factor for s[j]
static constexpr int TILE_I = 128;  // tiling factor for q[i]

// Initialize arrays using Halide to mirror the C init_array().
static void init_array(int m,
                       int n,
                       Halide::Buffer<num_t, 2> A,  // shape: (m, n) => A(j, i) == A[i][j] in C
                       Halide::Buffer<num_t, 1> r,  // length n
                       Halide::Buffer<num_t, 1> p)  // length m
{
    Var i("i"), j("j");

    Func init_p("init_p");
    Func init_r("init_r");
    Func init_A("init_A");

    // p[i] = (DATA_TYPE)(i % m) / m;
    init_p(i) = cast<num_t>(i % m) / cast<int>(m);

    // r[i] = (DATA_TYPE)(i % n) / n;
    init_r(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = (DATA_TYPE)(i * (j+1) % n) / n;
    // C layout: A[i][j] -> Halide: A(j, i)
    init_A(j, i) = cast<num_t>((i * (j + 1)) % n) / cast<int>(n);

    // Simple but reasonably efficient schedules for initialization.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // 1D inits: vectorize and parallelize across i.
    init_p.compute_root()
          .vectorize(i, vec_width)
          .parallel(i);

    init_r.compute_root()
          .vectorize(i, vec_width)
          .parallel(i);

    // 2D init for A: j (dim 0) is the innermost, contiguous dimension.
    // Parallelize across rows (i), vectorize across columns (j).
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_p.realize(p);
    init_r.realize(r);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from bicg.hpp / PolyBench)
    int n = N;  // number of rows of A, and length of r, q
    int m = M;  // number of columns of A, and length of p, s

    // Buffers corresponding to the C arrays.
    //
    // C: DATA_TYPE A[N][M]  -> Halide: Buffer<num_t,2> A(m, n)  with A(j, i) == A[i][j]
    // C: DATA_TYPE s[M]     -> Halide: Buffer<num_t,1> s(m)
    // C: DATA_TYPE q[N]     -> Halide: Buffer<num_t,1> q(n)
    // C: DATA_TYPE p[M]     -> Halide: Buffer<num_t,1> p(m)
    // C: DATA_TYPE r[N]     -> Halide: Buffer<num_t,1> r(n)
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 1> s(m);
    Halide::Buffer<num_t, 1> q(n);
    Halide::Buffer<num_t, 1> p(m);
    Halide::Buffer<num_t, 1> r(n);

    // Initialize data (equivalent to init_array in the C version).
    init_array(m, n, A, r, p);

    // Wrap input arrays in ImageParams for Halide.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");  // (m, n)
    ImageParam p_param(type_of<num_t>(), 1, "p_param");  // (m)
    ImageParam r_param(type_of<num_t>(), 1, "r_param");  // (n)

    A_param.set(A);
    p_param.set(p);
    r_param.set(r);

    // Halide variables.
    Var i("i"), j("j");

    // RDom extents derived from the input buffers (fixed for this problem size).
    RDom ri(0, r.dim(0).extent(), "ri");  // 0 .. n-1
    RDom rj(0, p.dim(0).extent(), "rj");  // 0 .. m-1

    // ------------------------------------------------------------------------
    // Halide formulation of the BiCG kernel.
    //
    // Original C kernel:
    //
    // for (i = 0; i < m; i++)
    //   s[i] = 0;
    // for (i = 0; i < n; i++) {
    //   q[i] = 0;
    //   for (j = 0; j < m; j++) {
    //     s[j] = s[j] + r[i] * A[i][j];
    //     q[i] = q[i] + A[i][j] * p[j];
    //   }
    // }
    //
    // Which is mathematically:
    //   s[j] = sum_{i=0..n-1} r[i] * A[i][j]   (A^T * r)
    //   q[i] = sum_{j=0..m-1} A[i][j] * p[j]   (A * p)
    // ------------------------------------------------------------------------

    // s[j] = sum_i r[i] * A[i][j]
    // Halide: A(i,j) => A_param(j, i)
    Func s_func("s");
    s_func(j) = cast<num_t>(0);
    s_func(j) += r_param(ri) * A_param(j, ri);

    // q[i] = sum_j A[i][j] * p[j]
    Func q_func("q");
    q_func(i) = cast<num_t>(0);
    q_func(i) += A_param(rj, i) * p_param(rj);

    // ------------------------------------------------------------------------
    // Optimized schedules
    //
    // Key ideas:
    //  - A is stored as A(j, i) with j (dimension 0) contiguous in memory.
    //  - For s[j], we want j as the innermost loop to get vector loads from
    //    A_param(j, ri), and we parallelize across tiles of j.
    //  - For q[i], we keep j (rj) innermost as well, vectorizing across rj
    //    so that accesses A_param(rj, i) are contiguous in memory, and we
    //    parallelize across tiles of i.
    //  - Both reductions are embarrassingly parallel across their pure
    //    dimensions (j and i), so we parallelize those while keeping the
    //    reduction domains serial to avoid races.
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // ---- Schedule for s_func (computes s[j] = (A^T * r)[j]) ----
    {
        Var jo("jo"), ji("ji");

        s_func.compute_root();

        // Initialization of s[j] = 0:
        //   - Tile j so that each task works on a moderately large chunk.
        //   - Parallelize across tiles.
        //   - Vectorize across the innermost chunk of j to use SIMD.
        s_func
            .split(j, jo, ji, TILE_J)
            .parallel(jo)
            .vectorize(ji, vec_width);

        // Reduction update:
        //   s[j] += r[ri] * A(j, ri)
        //
        // We:
        //   - Split j into tiles (jo, ji) as above.
        //   - Reorder loops so that:
        //       outermost: jo (tile index)     -> parallel
        //       middle:    ri (reduction)      -> serial
        //       innermost: ji (within tile)    -> vectorized
        //     This gives good locality and SIMD along the contiguous j dimension.
        s_func.update()
            .split(j, jo, ji, TILE_J)
            .reorder(ji, ri, jo)      // from innermost to outermost: ji, ri, jo
            .parallel(jo)
            .vectorize(ji, vec_width);
    }

    // ---- Schedule for q_func (computes q[i] = (A * p)[i]) ----
    {
        Var io("io"), ii("ii");

        q_func.compute_root();

        // Initialization of q[i] = 0:
        //   - Tile i.
        //   - Parallelize across tiles of i.
        //   - Vectorize within tiles across i (not critical, but cheap).
        q_func
            .split(i, io, ii, TILE_I)
            .parallel(io)
            .vectorize(ii, vec_width);

        // Reduction update:
        //   q[i] += A(rj, i) * p[rj]
        //
        // Default loop order is: for i (pure) { for rj (reduction) { ... } }
        // A_param(rj, i) is contiguous in rj (dim 0), so we:
        //   - Keep rj as the innermost loop and vectorize across rj to get
        //     SIMD vector loads/stores over the contiguous dimension.
        //   - Tile i into (io, ii), parallelizing across io; each tile of i
        //     is independent, so this is safe.
        q_func.update()
            .split(i, io, ii, TILE_I)
            .reorder(rj, ii, io)     // innermost: rj; then ii; outermost: io
            .parallel(io)
            .vectorize(rj, vec_width);
    }

    // JIT-compile both functions once, so timing measures only execution.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m), newline every 20 elements.
        std::cerr << "s:";
        for (int idx = 0; idx < m; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << s(idx) << ' ';
        }
        std::cerr << "\nq:";

        // Print q (length n), newline every 20 elements.
        for (int idx = 0; idx < n; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << q(idx) << ' ';
        }
        std::cerr << '\n';
    }

    // Print elapsed time in seconds (like gemm.cpp).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
