    RDom ri(0, r.dim(0).extent(), "ri");  // 0 .. n-1
    RDom rj(0, p.dim(0).extent(), "rj");  // 0 .. m-1

    // ------------------------------------------------------------------------
    // Halide formulation of the BiCG kernel.
    //
    // Original C kernel:
    //
    // for (i = 0; i < m; i++)
    //   s[i] = 0;
    // for (i = 0; i < n; i++) {
    //   q[i] = 0;
    //   for (j = 0; j < m; j++) {
    //     s[j] = s[j] + r[i] * A[i][j];
    //     q[i] = q[i] + A[i][j] * p[j];
    //   }
    // }
    //
    // Which is mathematically:
    //   s[j] = sum_{i=0..n-1} r[i] * A[i][j]   (A^T * r)
    //   q[i] = sum_{j=0..m-1} A[i][j] * p[j]   (A * p)
