        .compute_root()
        .split(i, io, ii, vec_width)
        .parallel(io)
        .vectorize(ii);

    q_func.update()
        .split(i, io, ii, vec_width)
        // From innermost to outermost: ii (vectorized), rj (reduction), io.
        .reorder(ii, rj, io)
        .parallel(io)
        .vectorize(ii);

