    // s[j] = sum_i r[i] * A[i][j]
    // Halide: A(i,j) => A_param(j, i)
    Func s_func("s");
    s_func(j) = cast<num_t>(0);
    s_func(j) += r_param(ri) * A_param(j, ri);

    // q[i] = sum_j A[i][j] * p[j]
    Func q_func("q");
    q_func(i) = cast<num_t>(0);
    q_func(i) += A_param(rj, i) * p_param(rj);

    // ------------------------------------------------------------------------
    // Optimized schedules
    //
    // We target a modern x86-64 CPU with SIMD and many cores.
    // A is stored such that A_param(j, i) is contiguous in memory along j,
    // so we:
    //   - vectorize over j where possible to get unit‑stride loads,
    //   - parallelize across independent output elements (j for s, i for q),
    //   - keep reduction variables (ri, rj) inside the parallel loops.
    // ------------------------------------------------------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;  // fallback, though on x64 this should be >= 4
    }

    // ---- Schedule for s_func: s[j] = sum_i r[i] * A(j, i) ----
    //
    // We parallelize over j and vectorize over small j tiles, keeping
    // the reduction over ri innermost-but-outside the vector lane.
    // This gives:
    //   for j_outer in parallel:
    //     for ri:
    //       for j_inner (vectorized):
    //         j = j_outer*vec_width + j_inner;
    //         s[j] += r[ri] * A(j, ri);
    Var j_outer("j_outer"), j_inner("j_inner");

    s_func.compute_root()
          .split(j, j_outer, j_inner, vec_width)
          .parallel(j_outer)
          .vectorize(j_inner);

    s_func.update()
          .split(j, j_outer, j_inner, vec_width)
          // Order from innermost outwards: j_inner (vectorized) inside,
          // then reduction variable ri, then the outer tile index j_outer.
          .reorder(j_inner, ri, j_outer)
          .parallel(j_outer)
          .vectorize(j_inner);

    // ---- Schedule for q_func: q[i] = sum_j A(j, i) * p[j] ----
    //
    // Each q[i] is independent, so we parallelize across i.
    // The reduction iterates over rj, which indexes the first (contiguous)
    // dimension of A_param and p_param, so we vectorize rj.
    //
    // Loop structure (conceptual):
    //   parallel for i:
    //     q[i] = 0;
    //   parallel for i:
    //     for rj in SIMD chunks:
    //       q[i] += A(rj, i) * p[rj];
    //
    q_func.compute_root()
          .parallel(i);

    q_func.update()
          // Make it explicit that rj is innermost (best for A_param & p_param).
          .reorder(rj, i)
          .parallel(i)
          .vectorize(rj, vec_width);

    // JIT-compile both functions once, so timing measures only execution.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m), newline every 20 elements.
        std::cerr << "s:";
        for (int idx = 0; idx < m; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << s(idx) << ' ';
        }
        std::cerr << "\nq:";

        // Print q (length n), newline every 20 elements.
        for (int idx = 0; idx < n; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << q(idx) << ' ';
        }
        std::cerr << '\n';
    }

    // Print elapsed time in seconds (like gemm.cpp).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
